const obj = {
  [Symbol.iterator]() {
    let i = 1;
    return {
      next() {
        return {
          done: i > 3,
          value: i > 3 ? undefined : i++,
        };
      },
    };
  },
};

for (value of obj) {
  console.log(value); // 1
  										// 2
  										// 3
}

const obj = {
	[Symbol.iterator]: function* () {
    let i = 1;
    while (i <= 3) {
      yield i++;
    }
  }
}

for (value of obj) {
  console.log(value); // 1
  										// 2
  										// 3
}
